// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        address nonWard = address(0x1234);
        vm.prank(nonWard);
        bool ok;
        try c.rely(address(this)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Reference should revert on non-ward rely");
    }
}
